// Extract incoming user query and match with database
const userQuery = ($input.first().json.body?.query || $input.first().json.query || "").toLowerCase();
const services = $('Fetch Google Sheet Data').all().map(item => item.json);

const keywords = ["hunger", "food", "rent", "medicine", "job", "shelter", "mental health"];
const detectedKeywords = keywords.filter(k => userQuery.includes(k));

const matchedServices = services.filter(service => {
  const fullText = JSON.stringify(service).toLowerCase();
  return detectedKeywords.some(k => fullText.includes(k)) || fullText.includes(userQuery);
});

return [{
  json: {
    userQuery: userQuery,
    detectedKeywords: detectedKeywords,
    matchedServices: matchedServices.slice(0, 3)
  }
}];

