// n8n Code Node: Aggregates logs and detects spikes in crisis queries
const items = $input.all();
const logEntries = items.map(item => (item.json.query || "").toLowerCase());

const trackedKeywords = ["hunger", "food", "rent", "medicine", "job", "shelter", "mental health"];
const keywordStats = {};

trackedKeywords.forEach(k => {
  keywordStats[k] = logEntries.filter(query => query.includes(k)).length;
});

// Identify any keywords exceeding threshold of 5 searches/day
const activeAlerts = Object.entries(keywordStats)
  .filter(([keyword, count]) => count >= 5)
  .map(([keyword, count]) => ({ keyword, count }));

return [{
  json: {
    date: new Date().toISOString().split('T')[0],
    totalQueries: logEntries.length,
    triggerAlert: activeAlerts.length > 0,
    activeAlerts: activeAlerts,
    keywordBreakdown: keywordStats
  }
}];

